export const BODY: string = "\n<p>WebP جدید اور چھوٹا ہے، مگر ہر جگہ نہیں کھلتا۔ JPG پرانا اور بڑا ہے، مگر ہر جگہ کھلتا ہے۔ یہ مضمون بتاتا ہے کہ کب WebP رکھیں اور کب JPG میں بدلیں۔</p>\n<p>مطابقت کا فیصلہ منزل پر منحصر ہے۔ ویب کے لیے WebP بہتر ہے، فارم اور پرنٹ کے لیے JPG۔ غلط فارمیٹ چننے سے تصویر کھلتی ہی نہیں۔</p>\n<p>یہ رہنما فارم، پرنٹر، ای میل اور پرانے سافٹ ویئر کا موازنہ کرتا ہے۔ تبدیل کرنے کے لیے <a href=\"/ur/webp-ko-jpg-mein-convert-karein/\">WebP ٹو JPG</a> استعمال کریں۔</p>\n<h2 id=\"compatibility-first\">مطابقت پہلے</h2>\n<p>مطابقت کا مطلب ہے کہ تصویر منزل پر کھلتی ہے یا نہیں۔ سب سے اچھی تصویر بھی بیکار ہے اگر وہ نہ کھلے۔</p>\n<p>مطابقت پہلے سوچیں، سائز بعد میں۔ WebP چھوٹا ہے، مگر اگر وہ فارم میں نہ کھلے تو اس کا کوئی فائدہ نہیں۔</p>\n<p>مطابقت جانچنے کا طریقہ یہ ہے کہ تصویر کو منزل کے سسٹم پر آزمائیں۔ اگر وہ کھل جائے تو فارمیٹ درست ہے۔</p>\n<h2 id=\"forms-and-portals\">فارم اور پورٹل</h2>\n<p>سرکاری فارم اور پورٹل اکثر صرف JPG اور PNG لیتے ہیں۔ WebP وہاں مسترد ہو جاتا ہے، اور فارم جمع نہیں ہوتا۔</p>\n<p>فارم کے لیے JPG چنیں، کیونکہ وہ ہر پورٹل میں کھلتا ہے۔ فارم جمع کرنے سے پہلے فارمیٹ جانچیں۔</p>\n<p>فارم کی ہدایت پڑھیں: وہ اکثر لکھتے ہیں کہ کون سے فارمیٹ قبول ہیں۔ ہدایت کے مطابق فارمیٹ چنیں۔</p>\n<h2 id=\"printers-and-print-shops\">پرنٹر اور پرنٹ شاپ</h2>\n<p>پرنٹر اور پرنٹ شاپ اکثر WebP نہیں لیتے۔ وہ JPG یا PNG مانگتے ہیں، کیونکہ ان کا سافٹ ویئر پرانا ہے۔</p>\n<p>پرنٹ کے لیے JPG چنیں۔ پرنٹ شاپ کو WebP بھیجنے سے کام رک جاتا ہے۔</p>\n<p>پرنٹ سے پہلے پرنٹ شاپ سے پوچھیں کہ وہ کون سا فارمیٹ لیتے ہیں۔ پوچھنا بہتر ہے، دوبارہ بھیجنے سے۔</p>\n<h2 id=\"email-clients\">ای میل کلائنٹ</h2>\n<p>ای میل کلائنٹ میں WebP اکثر نہیں کھلتا، خاص طور پر پرانے کلائنٹ میں۔ JPG ای میل میں ہمیشہ کھلتا ہے۔</p>\n<p>ای میل کے لیے JPG چنیں، تاکہ وصول کنندہ تصویر دیکھ سکے۔ WebP ای میل میں خالی ڈبہ بن جاتا ہے۔</p>\n<p>ای میل میں تصویر بھیجنے سے پہلے اسے خود کو بھیج کر جانچیں۔ اگر وہ کھل جائے تو فارمیٹ درست ہے۔</p>\n<h2 id=\"old-software\">پرانا سافٹ ویئر</h2>\n<p>پرانا سافٹ ویئر WebP نہیں کھولتا، کیونکہ WebP نیا فارمیٹ ہے۔ پرانے سافٹ ویئر میں JPG ہی چلتا ہے۔</p>\n<p>پرانے سافٹ ویئر کے لیے JPG نقل رکھیں۔ اصل WebP محفوظ رکھیں اور JPG نقل بھیجیں۔</p>\n<p>پرانے سافٹ ویئر کی پہچان یہ ہے کہ وہ 2018 سے پہلے کا ہے۔ اس سے پرانا سافٹ ویئر WebP نہیں جانتا۔</p>\n<h2 id=\"when-compression-wins\">کمپریشن کب جیتتی ہے</h2>\n<p>کمپریشن اس وقت جیتتی ہے جب تصویر ویب پر رہے۔ ویب پر WebP چھوٹا ہے اور تیز لوڈ ہوتا ہے، اس لیے وہ بہتر ہے۔</p>\n<p>کمپریشن اس وقت نہیں جیتتی جب تصویر کو کہیں بھیجنا ہو۔ بھیجنے میں مطابقت اہم ہے، سائز نہیں۔</p>\n<p>فیصلہ یہ ہے: ویب کے لیے WebP، بھیجنے کے لیے JPG۔ دونوں اپنی جگہ درست ہیں۔</p>\n<h2 id=\"hybrid-approach\">ہائبرڈ طریقہ</h2>\n<p>ہائبرڈ طریقہ یہ ہے کہ دونوں فارمیٹ رکھیں: WebP ویب کے لیے، JPG بھیجنے کے لیے۔ ایک ہی تصویر کی دو نقلیں۔</p>\n<p>ہائبرڈ طریقہ سے ہر جگہ کام چلتا ہے۔ ویب سائٹ WebP دکھاتی ہے، فارم JPG لیتا ہے۔</p>\n<p>ہائبرڈ طریقہ میں اصل WebP محفوظ رکھیں اور JPG نقل بنائیں۔ نقل بنانا آسان ہے، اصل بنانا مشکل۔</p>\n<h2 id=\"converting-strategy\">تبدیلی کی حکمت عملی</h2>\n<p>تبدیلی کی حکمت عملی یہ ہے کہ WebP کو JPG میں اس وقت بدلیں جب منزل WebP نہ لے۔ پہلے منزل جانچیں، پھر بدلیں۔</p>\n<p>تبدیلی سے پہلے اصل WebP محفوظ رکھیں۔ JPG میں بدلنے پر شفافیت ختم ہو جاتی ہے، اس لیے اصل بچانا ضروری ہے۔</p>\n<p>تبدیلی کا معیار 90 فیصد رکھیں، تاکہ تصویر صاف رہے۔ کم معیار پر تصویر خراب ہو جاتی ہے۔</p>\n<h2 id=\"measuring-the-tradeoff\">توازن کی پیمائش</h2>\n<p>توازن کی پیمائش یہ ہے کہ WebP کتنا چھوٹا ہے اور JPG کتنا مطابقت رکھتا ہے۔ دونوں کا فرق ناپیں۔</p>\n<p>اگر WebP JPG سے آدھا ہو تو ویب کے لیے WebP رکھیں۔ اگر فرق کم ہو تو JPG بھی چلتا ہے۔</p>\n<p>پیمائش کے لیے ایک ہی تصویر کو دونوں فارمیٹ میں محفوظ کریں اور سائز دیکھیں۔ فرق خود نظر آ جائے گا۔</p>\n<h2 id=\"future-of-webp\">WebP کا مستقبل</h2>\n<p>WebP کا مستقبل روشن ہے، کیونکہ نئے براؤزر اور سافٹ ویئر اسے لیتے ہیں۔ ہر سال WebP کی مطابقت بڑھ رہی ہے۔</p>\n<p>مستقبل میں WebP JPG کی جگہ لے سکتا ہے، مگر ابھی نہیں۔ پرانے سسٹم ابھی بھی JPG مانگتے ہیں۔</p>\n<p>مستقبل کی تیاری یہ ہے کہ اصل WebP میں رکھیں اور JPG نقل بنائیں۔ جب WebP ہر جگہ کھلنے لگے تو نقل کی ضرورت نہیں رہے گی۔</p>\n<h2 id=\"decision-checklist\">فیصلے کی چیک لسٹ</h2>\n<p>چیک لسٹ یہ ہے: منزل کیا ہے؟ کیا وہ WebP لیتی ہے؟ اگر ہاں تو WebP رکھیں، اگر نہیں تو JPG میں بدلیں۔</p>\n<p>چیک لسٹ کا دوسرا نکتہ یہ ہے: کیا شفافیت چاہیے؟ اگر ہاں تو JPG نہ چنیں، کیونکہ وہ شفافیت مٹاتا ہے۔</p>\n<p>چیک لسٹ کا تیسرا نکتہ یہ ہے: کیا فائل کا سائز اہم ہے؟ اگر ہاں تو WebP رکھیں، اگر نہیں تو JPG چلتا ہے۔</p>\n<h2 id=\"compatibility-schools-offices\">اسکول اور دفتر کی مطابقت</h2>\n<p>اسکول اور دفتر میں پرانا سافٹ ویئر چلتا ہے، جو WebP نہیں کھولتا۔ اسکول کو تصویر بھیجنے کے لیے JPG چنیں۔</p>\n<p>اسکول کے کمپیوٹر پر WebP کھولنے کی کوشش نہ کریں۔ وہ اکثر پرانے ونڈوز پر چلتے ہیں۔</p>\n<p>دفتر کے لیے بھی JPG محفوظ ہے۔ دفتر کا سافٹ ویئر بدلنے میں دیر لگتی ہے۔</p>\n<h2 id=\"compatibility-government\">سرکاری دفاتر کی مطابقت</h2>\n<p>سرکاری دفاتر میں سب سے پرانا سافٹ ویئر چلتا ہے۔ وہ صرف JPG اور PNG لیتے ہیں، WebP نہیں۔</p>\n<p>سرکاری فارم کے لیے JPG چنیں۔ WebP بھیجنے سے فارم مسترد ہو جاتا ہے۔</p>\n<p>سرکاری دفتر کو تصویر بھیجنے سے پہلے فارمیٹ جانچیں۔ غلط فارمیٹ سے کام رک جاتا ہے۔</p>\n<h2 id=\"compatibility-old-phones\">پرانے فون کی مطابقت</h2>\n<p>پرانے فون WebP نہیں کھولتے، خاص طور پر 2018 سے پہلے کے۔ پرانے فون کے لیے JPG چنیں۔</p>\n<p>پرانے فون پر WebP بھیجنے سے تصویر کھلتی ہی نہیں۔ وصول کنندہ خالی ڈبہ دیکھتا ہے۔</p>\n<p>پرانے فون کی پہچان یہ ہے کہ اس کا سافٹ ویئر اپ ڈیٹ نہیں ہوتا۔ ایسے فون کے لیے JPG محفوظ ہے۔</p>\n<h2 id=\"compatibility-design-software\">ڈیزائن سافٹ ویئر کی مطابقت</h2>\n<p>ڈیزائن سافٹ ویئر میں WebP کی سپورٹ بڑھ رہی ہے، مگر پرانے ورژن نہیں لیتے۔ ڈیزائن کے لیے PNG چنیں۔</p>\n<p>ڈیزائن سافٹ ویئر میں WebP کھولنے سے پہلے ورژن جانچیں۔ نیا ورژن WebP لیتا ہے، پرانا نہیں۔</p>\n<p>ڈیزائن کے لیے اصل WebP محفوظ رکھیں اور کام کے لیے PNG نقل بنائیں۔</p>\n<h2 id=\"planning-future-formats\">مستقبل کے فارمیٹ کی منصوبہ بندی</h2>\n<p>مستقبل کے فارمیٹ کی منصوبہ بندی یہ ہے کہ اصل کو جدید فارمیٹ میں رکھیں اور نقل کو پرانے میں۔ اصل WebP، نقل JPG۔</p>\n<p>منصوبہ بندی سے آپ ہر منزل کے لیے تیار رہتے ہیں۔ نیا سسٹم WebP لیتا ہے، پرانا JPG۔</p>\n<p>منصوبہ بندی کا آخری نکتہ یہ ہے کہ ہر سال مطابقت جانچیں۔ جیسے جیسے WebP پھیلتا ہے، JPG کی ضرورت کم ہوتی جاتی ہے۔ تبدیلی کے مراحل <a href=\"/ur/blog/webp-ko-jpg-mein-kaise-convert-karein/\">WebP کو JPG میں کیسے بدلیں</a> میں اور مکمل گائیڈ <a href=\"/ur/blog/webp-ko-jpg-rehnumai/\">WebP ٹو JPG گائیڈ</a> میں دیکھیں۔</p>\n";

